import { renderToString } from 'react-dom/server';
import { test, expect } from 'vitest';
import { ThemeProvider } from '@gravity-ui/uikit';
import { DataTable } from './DataTable';

const data = [
  { id: '1', name: 'Борис', n: 3 }, { id: '2', name: 'анна', n: 10 }, { id: '3', name: 'Вера', n: 2 },
  { id: '4', name: '', n: 1 }, { id: '5', name: 'Глеб', n: 5 },
];
const cols = [{ id: 'name', name: 'Имя', sortable: true }, { id: 'n', name: 'N', sortable: true }];
const render = (sort: any, selected: string[] = []) => renderToString(
  <ThemeProvider theme="light"><DataTable data={data} columns={cols} getRowId={(i) => i.id}
    selectedIds={selected} onSelectionChange={() => {}} defaultSortState={sort} pageSizeOptions={[3, 10]} /></ThemeProvider>);
const rows = (html: string) => [...html.matchAll(/<tr[^>]*g-table__row[^>]*>(.*?)<\/tr>/g)].map(m => m[1].replace(/<[^>]+>/g, '|').split('|').filter(Boolean).join(' '));

test('ssr', () => {
  console.log(rows(render([{ column: 'name', order: 'asc' }])));
  console.log(rows(render([{ column: 'name', order: 'desc' }])));
  console.log(rows(render([{ column: 'n', order: 'desc' }])));
  const h = render([], ['1', '3']);
  console.log('checkboxes', (h.match(/type="checkbox"/g) || []).length, 'selected rows', (h.match(/g-table__row_selected/g) || []).length, 'sort btns', (h.match(/g-table__sort/g)||[]).length);
  expect(h).toContain('Выбрано: 2 из 5');
});
EOF
